using System.Diagnostics;using System.Security.Claims;
namespace Commerce.Operations.Api.Audit;
public sealed class AuditMiddleware(AuditRepository repository,ILogger<AuditMiddleware> logger):IMiddleware{private static readonly HashSet<string> Mutating=["POST","PUT","PATCH","DELETE"];
 public async Task InvokeAsync(HttpContext context,RequestDelegate next){var watch=Stopwatch.StartNew();await next(context);watch.Stop();if(!Mutating.Contains(context.Request.Method)||!context.Request.Path.StartsWithSegments("/api")||context.Request.Path.StartsWithSegments("/api/auth")||context.User.Identity?.IsAuthenticated!=true)return;try{long? id=long.TryParse(context.User.FindFirstValue(ClaimTypes.NameIdentifier),out var value)?value:null;await repository.WriteAsync(id,context.User.FindFirstValue(ClaimTypes.Email)??"unknown",context.Request.Method,context.Request.Path.Value??"/",context.Response.StatusCode,watch.ElapsedMilliseconds,context.Connection.RemoteIpAddress?.ToString(),context.Request.Headers.UserAgent.ToString());}catch(Exception exception){logger.LogError(exception,"Failed to persist audit log for {Method} {Path}",context.Request.Method,context.Request.Path);}}}
